     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Support Contact Form</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #0b1120;
         --panel: #111827;
         --panel-border: #243041;
         --text: #e5edf7;
         --muted: #9fb0c7;
         --accent: #7dd3fc;
         --accent-strong: #38bdf8;
         --field-bg: #0f172a;
         --field-border: #334155;
         --field-border-focus: #7dd3fc;
         --error: #fda4af;
         --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
       }

       * {
         box-sizing: border-box;
       }

       html,
       body {
         margin: 0;
         min-height: 100%;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
           "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top, rgba(56, 189, 248, 0.12), transparent 35%),
           linear-gradient(180deg, #020617 0%, var(--bg) 100%);
         color: var(--text);
       }

       body {
         display: flex;
         align-items: center;
         justify-content: center;
         padding: 24px;
       }

       .skip-link {
         position: absolute;
         top: 12px;
         left: 12px;
         transform: translateY(-200%);
         padding: 0.75rem 1rem;
         border-radius: 0.75rem;
         background: var(--text);
         color: #020617;
         font-weight: 700;
         text-decoration: none;
       }

       .skip-link:focus {
         transform: translateY(0);
         outline: 2px solid var(--accent);
         outline-offset: 2px;
       }

       .page-shell {
         width: min(100%, 760px);
       }

       .support-card {
         padding: clamp(24px, 4vw, 40px);
         border: 1px solid var(--panel-border);
         border-radius: 24px;
         background: linear-gradient(180deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.96));
         box-shadow: var(--shadow);
       }

       .eyebrow {
         display: inline-flex;
         margin: 0 0 1rem;
         padding: 0.35rem 0.7rem;
         border: 1px solid rgba(125, 211, 252, 0.25);
         border-radius: 999px;
         color: var(--accent);
         background: rgba(14, 165, 233, 0.08);
         font-size: 0.875rem;
         font-weight: 600;
         letter-spacing: 0.02em;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 4vw, 2.8rem);
         line-height: 1.1;
       }

       .intro {
         margin: 1rem 0 0;
         max-width: 60ch;
         color: var(--muted);
         font-size: 1rem;
         line-height: 1.65;
       }

       form {
         margin-top: 2rem;
       }

       .form-grid {
         display: grid;
         gap: 1.25rem;
       }

       .form-field {
         display: flex;
         flex-direction: column;
         gap: 0.55rem;
       }

       label {
         font-size: 0.95rem;
         font-weight: 600;
       }

       .required-indicator {
         color: var(--accent);
       }

       input {
         width: 100%;
         padding: 0.95rem 1rem;
         border: 1px solid var(--field-border);
         border-radius: 14px;
         background: var(--field-bg);
         color: var(--text);
         font: inherit;
       }

       input::placeholder {
         color: #7c8da6;
       }

       input:hover {
         border-color: #475569;
       }

       input:focus {
         outline: 2px solid transparent;
         border-color: var(--field-border-focus);
         box-shadow: 0 0 0 4px rgba(125, 211, 252, 0.16);
       }

       input[aria-invalid="true"] {
         border-color: var(--error);
       }

       .field-helper,
       .error-message,
       .status-message {
         margin: 0;
         font-size: 0.9rem;
         line-height: 1.5;
       }

       .field-helper {
         color: var(--muted);
       }

       .error-message {
         color: var(--error);
       }

       .status-message {
         min-height: 1.5em;
         margin-top: 1rem;
         color: var(--accent);
       }

       .submit-button {
         margin-top: 1.75rem;
         display: inline-flex;
         align-items: center;
         justify-content: center;
         min-width: 160px;
         padding: 0.95rem 1.4rem;
         border: 1px solid rgba(125, 211, 252, 0.25);
         border-radius: 999px;
         background: linear-gradient(135deg, var(--accent-strong), #0ea5e9);
         color: #03111f;
         font: inherit;
         font-weight: 800;
         cursor: pointer;
       }

       .submit-button:hover {
         filter: brightness(1.05);
       }

       .submit-button:focus {
         outline: 2px solid var(--text);
         outline-offset: 3px;
       }

       @media (max-width: 480px) {
         body {
           padding: 16px;
         }

         .support-card {
           border-radius: 20px;
         }
       }

       @media (forced-colors: active) {
         .support-card,
         input,
         .submit-button,
         .skip-link,
         .eyebrow {
           border-color: ButtonText;
         }

         .support-card,
         input {
           background: Canvas;
           color: CanvasText;
         }

         .submit-button,
         .skip-link {
           background: ButtonFace;
           color: ButtonText;
         }

         .field-helper,
         .error-message,
         .status-message,
         .intro,
         .eyebrow {
           color: CanvasText;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="app"></div>
     <script>
       const createField = ({
         id,
         label,
         type = "text",
         required = false,
         autoComplete = "off",
         placeholder = "",
         helperText = "",
       }) => `
         <div class="form-field">
           <label for="${id}">
             ${label}${required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
           </label>
           <input
             id="${id}"
             name="${id}"
             type="${type}"
             ${required ? "required aria-required=\"true\"" : ""}
             autocomplete="${autoComplete}"
             placeholder="${placeholder}"
             ${helperText ? `aria-describedby="${id}-helper ${id}-error"` : `aria-describedby="${id}-error"`}
           />
           ${
             helperText
               ? `<p class="field-helper" id="${id}-helper">${helperText}</p>`
               : ""
           }
           <p class="error-message" id="${id}-error" hidden></p>
         </div>
       `;

       const ContactForm = () => `
         <main id="main-content" class="page-shell">
           <section class="support-card" aria-labelledby="support-title">
             <p class="eyebrow">Support</p>
             <h1 id="support-title">Contact our support team</h1>
             <p class="intro">
               Share a few details and we will follow up with the right next step as soon as possible.
             </p>
             <form id="support-form" novalidate>
               <div class="form-grid">
                 ${createField({
                   id: "fullName",
                   label: "Full name",
                   required: true,
                   autoComplete: "name",
                   placeholder: "Taylor Morgan",
                 })}
                 ${createField({
                   id: "emailAddress",
                   label: "Email address",
                   type: "email",
                   required: true,
                   autoComplete: "email",
                   placeholder: "taylor@example.com",
                 })}
                 ${createField({
                   id: "phoneNumber",
                   label: "Phone number",
                   type: "tel",
                   autoComplete: "tel",
                   placeholder: "(555) 123-4567",
                   helperText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567.",
                 })}
               </div>
               <button class="submit-button" type="submit">Submit</button>
               <p class="status-message" id="form-status" aria-live="polite"></p>
             </form>
           </section>
         </main>
       `;

       const App = () => ContactForm();

       document.getElementById("app").innerHTML = App();

       const form = document.getElementById("support-form");
       const status = document.getElementById("form-status");
       const fullName = document.getElementById("fullName");
       const emailAddress = document.getElementById("emailAddress");
       const phoneNumber = document.getElementById("phoneNumber");

       const validators = {
         fullName: (value) => (value.trim() ? "" : "Enter your full name."),
         emailAddress: (value) => {
           if (!value.trim()) return "Enter your email address.";
           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
             ? ""
             : "Enter a valid email address.";
         },
         phoneNumber: (value) => {
           if (!value.trim()) return "";
           return /^[+]?[0-9\s().-]{7,20}$/.test(value)
             ? ""
             : "Use a phone number like (555) 123-4567 or +1 555 123 4567.";
         },
       };

       const fieldMap = {
         fullName,
         emailAddress,
         phoneNumber,
       };

       const setFieldError = (field, message) => {
         const errorElement = document.getElementById(`${field.id}-error`);
         field.setAttribute("aria-invalid", message ? "true" : "false");
         errorElement.textContent = message;
         errorElement.hidden = !message;
       };

       const validateField = (field) => {
         const message = validators[field.id](field.value);
         setFieldError(field, message);
         return !message;
       };

       [fullName, emailAddress, phoneNumber].forEach((field) => {
         field.addEventListener("blur", () => {
           validateField(field);
         });

         field.addEventListener("input", () => {
           if (field.getAttribute("aria-invalid") === "true") {
             validateField(field);
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         status.textContent = "";

         const fields = Object.values(fieldMap);
         const invalidField = fields.find((field) => !validateField(field));

         if (invalidField) {
           status.textContent = "Please fix the highlighted fields and try again.";
           invalidField.focus();
           return;
         }

         status.textContent = "Your message is ready to send.";
       });
     </script>
   </body>
 </html>

')
